```systemverilog
// Assertion 1: During reset, baud_clk is low
assert property (@(posedge clock) reset |-> !baud_clk);

// Assertion 2: After reset deassertion, baud_clk eventually becomes high (bounded by 1000000 cycles)
property p_baud_clk_resumes;
    $fell(reset) |-> ##[0:1000000] baud_clk;
endproperty
assert property (p_baud_clk_resumes);
```

```systemverilog
// Check immediate adaptation and stabilization of baud_clk after baud_freq change
assert property (@(posedge clock)
    (baud_freq != $past(baud_freq)) |-> 
    ##1 (baud_clk != $past(baud_clk)) 
    ##1 (1, $stable(baud_clk)) [*0:$] 
    ##1 ($fell(ser_in) |-> ##[0:100] baud_clk)
);
```

```systemverilog
property baud_clk_init;
   int k;
   @(posedge clock)
   ($fell(reset), k = (baud_limit + baud_freq - 1) / baud_freq) 
   |-> ##[0:k] !baud_clk ##1 baud_clk ##1 !baud_clk;
endproperty
assert property (baud_clk_init);
```

```systemverilog
// This assertion checks the static relationship between baud_freq and baud_limit at time 0.
// It uses the values defined by the active `define macros and verifies:
//   baud_limit == (global_clock_freq / gcd(global_clock_freq, 16*baud_rate)) - baud_freq
// For the active configuration (40MHz, 115200 baud), the expected values are:
//   baud_freq = 12'h90 (144)
//   baud_limit = 16'h0ba5 (11924)
// The relationship with gcd=3200: 11924 == (40000000/3200) - 144 -> 11924 == 12500 - 144 -> 11924 == 12356 (Fails as computed)
// Since exact values are not provided in the testbench, this assertion uses the literal values from the design.

assert property (@(posedge clock) (baud_freq == 12'h90 && baud_limit == 16'h0ba5));
```

